//! Replays `vectors/runner/*.json`: the real `loadConfig` of
//! `apps/runner/src/config.ts` and Node's dotenv parser (`util.parseEnv`),
//! generated by `node scripts/vectors/index.ts runner`.
#![allow(
	clippy::unwrap_used,
	clippy::expect_used,
	clippy::panic,
	clippy::indexing_slicing
)]

use research_runner::config::{self, Env};
use research_runner::env_file;
use serde_json::Value;

fn vectors(name: &str) -> Value {
	let path = format!("{}/../../vectors/runner/{name}", env!("CARGO_MANIFEST_DIR"));
	serde_json::from_str(&std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{path}: {e}")))
		.unwrap()
}

fn optional(value: &Value) -> Option<String> {
	value.as_str().map(str::to_owned)
}

#[test]
fn config_matches_the_typescript_loader() {
	let file = vectors("config.json");
	let cases = file["cases"].as_array().unwrap();
	assert!(cases.len() > 1000);
	let (mut valid, mut invalid) = (0, 0);
	for case in cases {
		let env: Env = case["env"]
			.as_object()
			.unwrap()
			.iter()
			.map(|(key, value)| (key.clone(), value.as_str().unwrap().to_owned()))
			.collect();
		let result = &case["result"];
		match config::load(&env) {
			Ok(loaded) => {
				valid += 1;
				assert_eq!(result["ok"], true, "{env:?}");
				let expected = &result["value"];
				let context = format!("{env:?}");
				assert_eq!(expected["apiUrl"], loaded.api_url, "{context}");
				assert_eq!(expected["runnerToken"], loaded.runner_token, "{context}");
				assert_eq!(
					optional(&expected["accessClientId"]),
					loaded.access_client_id,
					"{context}"
				);
				assert_eq!(
					optional(&expected["accessClientSecret"]),
					loaded.access_client_secret,
					"{context}"
				);
				assert_eq!(
					optional(&expected["secUserAgent"]),
					loaded.sec_user_agent,
					"{context}"
				);
				assert_eq!(
					expected["allowUnverifiedToolIsolation"],
					loaded.allow_unverified_tool_isolation,
					"{context}"
				);
				assert_eq!(
					optional(&expected["scratchRoot"]),
					loaded.scratch_root,
					"{context}"
				);
				assert_eq!(
					optional(&expected["pagesDirectory"]),
					loaded.pages_directory,
					"{context}"
				);
				assert_eq!(
					optional(&expected["fredApiKey"]),
					loaded.fred_api_key,
					"{context}"
				);
				assert_eq!(
					optional(&expected["twelveDataApiKey"]),
					loaded.twelve_data_api_key,
					"{context}"
				);
				assert_eq!(
					optional(&expected["finnhubApiKey"]),
					loaded.finnhub_api_key,
					"{context}"
				);
				assert_eq!(
					optional(&expected["googleOAuthClientId"]),
					loaded.google_oauth_client_id,
					"{context}"
				);
				assert_eq!(
					optional(&expected["googleOAuthClientSecret"]),
					loaded.google_oauth_client_secret,
					"{context}"
				);
				assert_eq!(
					expected["googleTokenFile"], loaded.google_token_file,
					"{context}"
				);
				assert_eq!(
					expected["twelveDataRequestsPerMinute"], loaded.twelve_data_requests_per_minute,
					"{context}"
				);
				assert_eq!(
					expected["twelveDataDailyLimit"], loaded.twelve_data_daily_limit,
					"{context}"
				);
			}
			Err(problems) => {
				invalid += 1;
				assert_eq!(result["ok"], false, "{env:?}");
				let expected: Vec<&str> = result["problems"]
					.as_array()
					.unwrap()
					.iter()
					.map(|problem| problem.as_str().unwrap())
					.collect();
				assert_eq!(problems, expected, "{env:?}");
			}
		}
	}
	assert!(
		valid > 100 && invalid > 100,
		"{valid} valid, {invalid} invalid"
	);
}

#[test]
fn env_files_parse_like_node() {
	let file = vectors("env_file.json");
	let cases = file["cases"].as_array().unwrap();
	assert!(cases.len() > 5000);
	for case in cases {
		let text = case["text"].as_str().unwrap();
		let expected: Vec<(String, String)> = case["parsed"]
			.as_array()
			.unwrap()
			.iter()
			.map(|pair| {
				(
					pair[0].as_str().unwrap().to_owned(),
					pair[1].as_str().unwrap().to_owned(),
				)
			})
			.collect();
		let actual: Vec<(String, String)> = env_file::parse(text).into_iter().collect();
		assert_eq!(actual, expected, "{text:?}");
	}
}
